const table = new Map(rows.map(([kk,ru,en])=>[kk,{kk,ru,en}]));
let language='kk';try{const saved=localStorage.getItem('nout-language');if(['kk','ru','en'].includes(saved))language=saved;}catch{}
export const getLanguage=()=>language;
export function setLanguage(value){language=['kk','ru','en'].includes(value)?value:'kk';try{localStorage.setItem('nout-language',language);}catch{}document.documentElement.lang=language;}
export function tr(source){
 if(source==null)return '';const original=String(source),key=original.trim();if(language==='kk')return original;
 if(table.has(key))return original.replace(key,table.get(key)[language]);
 const ru=language==='ru';
 let m;
 if((m=key.match(/^(\d+) ноутбук$/)))return `${m[1]} ${ru?'ноутбуков':'laptops'}`;
 if((m=key.match(/^табылды\s*·\s*(\d+) модель ішінен$/)))return ru?`найдено · из ${m[1]} моделей`:`found · from ${m[1]} models`;
 if(key==='табылды')return ru?'найдено':'found';
 if((m=key.match(/^· (\d+) модель ішінен$/)))return ru?`· из ${m[1]} моделей`:`· from ${m[1]} models`;
 if((m=key.match(/^Тағы (\d+) ноутбук көрсету$/)))return ru?`Показать ещё ${m[1]} ноутбуков`:`Show ${m[1]} more laptops`;
 if((m=key.match(/^(\d+) \/ (\d+) көрсетілді(.*)$/)))return `${m[1]} / ${m[2]} ${ru?'показано · Цены условные. Архивные данные помечены отдельно.':'shown · Illustrative prices. Archive records are marked separately.'}`;
 if((m=key.match(/^(\d+) \/ 3 қадам · Шамамен бір минут$/)))return `${m[1]} / 3 · ${ru?'Около минуты':'About a minute'}`;
 if((m=key.match(/^(\d+) ноутбуктің сипаттамаларын салыстыр\.$/)))return ru?`Сравни характеристики ${m[1]} ноутбуков.`:`Compare specifications of ${m[1]} laptops.`;
 if((m=key.match(/^(\d+) (ГБ|ТБ) және одан көп$/)))return ru?`${m[1]} ${m[2]} и больше`:`${m[1]} ${m[2]==='ТБ'?'TB':'GB'} or more`;
 if((m=key.match(/^(\d+) (?:ГБ|GB)\+ RAM$/)))return `RAM ≥ ${m[1]} ${ru?'ГБ':'GB'}`;
 if((m=key.match(/^(.+)\+ сақтау орны$/)))return `${ru?'Накопитель':'Storage'} ≥ ${tr(m[1])}`;
 if((m=key.match(/^(.+) кг дейін$/)))return ru?`До ${m[1]} кг`:`Up to ${m[1]} kg`;
 if((m=key.match(/^(.+) ₸ дейін$/)))return ru?`До ${m[1]} ₸`:`Up to ${m[1]} ₸`;
 const prefixes=[['Таңдаулыларға қосу:','Добавить в избранное:','Save:'],['Таңдаулылардан алып тастау:','Убрать из избранного:','Unsave:'],['Салыстыруға қосу:','Добавить к сравнению:','Compare:'],['Салыстырудан алып тастау:','Убрать из сравнения:','Remove from comparison:'],['Сүзгіні алып тастау:','Убрать фильтр:','Remove filter:']];
 for(const [kk,r,e]of prefixes)if(key.startsWith(kk))return `${ru?r:e} ${tr(key.slice(kk.length).trim())}`;
 if(/^[≈\d.,\s]+\sкг$/.test(key))return ru?key:key.replace('кг','kg');
 if(/^[\d.,]+″ экран$/.test(key))return key.replace('экран',ru?'экран':'display');
 if(/^\d+ (ГБ|ТБ)( RAM)?$/.test(key))return ru?key:key.replace('ГБ','GB').replace('ТБ','TB');
 if(/сериясы$/.test(key))return key.replace('сериясы',ru?'серия':'series');
 return original;
}
const originals=new WeakMap();
export function translateDOM(root=document.body){
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;
 while((node=walker.nextNode())){if(['SCRIPT','STYLE','TEXTAREA'].includes(node.parentElement?.tagName))continue;const old=originals.get(node);const source=old&&node.nodeValue===old.last?old.source:node.nodeValue;const value=tr(source);originals.set(node,{source,last:value});if(node.nodeValue!==value)node.nodeValue=value;}
 const elements=root.querySelectorAll('[aria-label],[placeholder],[title]');
 for(const el of elements){let store=originals.get(el)||{};for(const attr of ['aria-label','placeholder','title']){if(!el.hasAttribute(attr))continue;const current=el.getAttribute(attr),prev=store[attr];const source=prev&&prev.last===current?prev.source:current;const last=tr(source);el.setAttribute(attr,last);store[attr]={source,last};}originals.set(el,store);}
 document.documentElement.lang=language;
 document.title=language==='ru'?'Nout — Найди свой ноутбук':language==='en'?'Nout — Find your laptop':'Nout — Өзіңе сай ноутбук';
}
export const localized=(kk,ru,en)=>({kk,ru,en}[language]);
export const translationRows=rows;
